/**
 * What the UI draws for one deck, read in one go.
 */
public struct DeckState: Equatable, Hashable {
    public var deck: String
    public var loaded: Bool
    public var playing: Bool
    public var composing: Bool
    public var genre: String?
    public var seed: Int64?
    /**
     * None: an endless loop.
     */
    public var structure: String?
    /**
     * "Solar Colimit".
     */
    public var title: String?
    public var tempo: Double
    public var baseTempo: Double
    /**
     * -1..1 of `pitch_range`.
     */
    public var pitch: Double
    public var pitchRange: Double
    public var volume: Double
    public var tick: Int64
    /**
     * `tick` plus the fraction of it played (the mirror's tick phase, per audio block): the
     * playhead the UI draws and extrapolates between polls.
     */
    public var position: Double
    public var totalTicks: Int64
    public var bar: Int64
    public var totalBars: Int64
    public var section: String?
    public var sections: [Section]
    /**
     * The deck's peak, 0..1.
     */
    public var level: Float
    public var palette: String
    /**
     * The last thing that went wrong (a compose that made no track, …).
     */
    public var message: String?
    /**
     * Auto-next every N bars (djrust docs/AUTO-NEXT.md): on, N, and bars left counting the
     * one playing (None while it is off or not counting: stopped, nothing composed).
     */
    public var autoNextOn: Bool
    public var autoNextBars: UInt32
    public var autoNextLeft: UInt32?
    /**
     * The seed the deck is composing to (an auto-next step or a Compose on its way in).
     */
    public var nextSeed: Int64?
    /**
     * At a song's end, play its next version (the next generated seed, Swift's
     * `autoAdvance`): the engine keeps it composed while the song plays.
     */
    public var autoAdvance: Bool
    /**
     * The seed [`Player::next_track`] plays: the next version's (None before a track).
     */
    public var nextVersionSeed: Int64?
    /**
     * A track played before this one, for [`Player::previous_track`].
     */
    public var hasPrevious: Bool
    /**
     * The song's roles in mixer order (empty before a track).
     */
    public var roles: [RoleState]
    /**
     * The TD-3 loop on the deck ("1A"), None for a composed track.
     */
    public var td3: String?
    /**
     * What auto level does to the deck now, dB (0 while it is off).
     */
    public var autoGainDb: Double

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(deck: String, loaded: Bool, playing: Bool, composing: Bool, genre: String?, seed: Int64?, 
        /**
         * None: an endless loop.
         */structure: String?, 
        /**
         * "Solar Colimit".
         */title: String?, tempo: Double, baseTempo: Double, 
        /**
         * -1..1 of `pitch_range`.
         */pitch: Double, pitchRange: Double, volume: Double, tick: Int64, 
        /**
         * `tick` plus the fraction of it played (the mirror's tick phase, per audio block): the
         * playhead the UI draws and extrapolates between polls.
         */position: Double, totalTicks: Int64, bar: Int64, totalBars: Int64, section: String?, sections: [Section], 
        /**
         * The deck's peak, 0..1.
         */level: Float, palette: String, 
        /**
         * The last thing that went wrong (a compose that made no track, …).
         */message: String?, 
        /**
         * Auto-next every N bars (djrust docs/AUTO-NEXT.md): on, N, and bars left counting the
         * one playing (None while it is off or not counting: stopped, nothing composed).
         */autoNextOn: Bool, autoNextBars: UInt32, autoNextLeft: UInt32?, 
        /**
         * The seed the deck is composing to (an auto-next step or a Compose on its way in).
         */nextSeed: Int64?, 
        /**
         * At a song's end, play its next version (the next generated seed, Swift's
         * `autoAdvance`): the engine keeps it composed while the song plays.
         */autoAdvance: Bool, 
        /**
         * The seed [`Player::next_track`] plays: the next version's (None before a track).
         */nextVersionSeed: Int64?, 
        /**
         * A track played before this one, for [`Player::previous_track`].
         */hasPrevious: Bool, 
        /**
         * The song's roles in mixer order (empty before a track).
         */roles: [RoleState], 
        /**
         * The TD-3 loop on the deck ("1A"), None for a composed track.
         */td3: String?, 
        /**
         * What auto level does to the deck now, dB (0 while it is off).
         */autoGainDb: Double) {
        self.deck = deck
        self.loaded = loaded
        self.playing = playing
        self.composing = composing
        self.genre = genre
        self.seed = seed
        self.structure = structure
        self.title = title
        self.tempo = tempo
        self.baseTempo = baseTempo
        self.pitch = pitch
        self.pitchRange = pitchRange
        self.volume = volume
        self.tick = tick
        self.position = position
        self.totalTicks = totalTicks
        self.bar = bar
        self.totalBars = totalBars
        self.section = section
        self.sections = sections
        self.level = level
        self.palette = palette
        self.message = message
        self.autoNextOn = autoNextOn
        self.autoNextBars = autoNextBars
        self.autoNextLeft = autoNextLeft
        self.nextSeed = nextSeed
        self.autoAdvance = autoAdvance
        self.nextVersionSeed = nextVersionSeed
        self.hasPrevious = hasPrevious
        self.roles = roles
        self.td3 = td3
        self.autoGainDb = autoGainDb
    }

    

    
}

