public 
enum DjError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case Audio(String
    )
    case Spec(String
    )
    case NoDeck(String
    )
    case Vocoder(String
    )
    case Heos(String
    )
    case Closed

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DjError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDjError: FfiConverterRustBuffer {
    typealias SwiftType = DjError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DjError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Audio(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .Spec(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .NoDeck(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .Vocoder(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .Heos(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .Closed

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DjError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Audio(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Spec(v1):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .NoDeck(v1):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Vocoder(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .Heos(v1):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .Closed:
            writeInt(&buf, Int32(6))
        
        }
    }
}


